from math import gcd

def lcm(a, b):
    return abs(a*b) // gcd(a, b) if a and b else 0

def list_lcm(numbers):
    if not numbers:
        return 1
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = lcm(result, numbers[i])
    return result

def list_gcd(numbers):
    if not numbers:
        return 0
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = gcd(result, numbers[i])
    return result

# Example sequence: a1=2, a2=6, a3=10, a4=30
A = [2, 6, 10, 30]
print(f"Sequence A: {A}")

# Check k=1 partition: A1={2}, B1={6, 10, 30}
lcm_A1 = list_lcm([A[0]])
gcd_B1 = list_gcd(A[1:])
print(f"k=1: LCM(A1)={lcm_A1}, GCD(B1)={gcd_B1}. Match? {lcm_A1 == gcd_B1}")

# Check k=2 partition: A2={2, 6}, B2={10, 30}
lcm_A2 = list_lcm(A[:2])
gcd_B2 = list_gcd(A[2:])
print(f"k=2: LCM(A2)={lcm_A2}, GCD(B2)={gcd_B2}. Match? {lcm_A2 == gcd_B2}")

# Check k=3 partition: A3={2, 6, 10}, B3={30}
lcm_A3 = list_lcm(A[:3])
gcd_B3 = list_gcd(A[3:])
print(f"k=3: LCM(A3)={lcm_A3}, GCD(B3)={gcd_B3}. Match? {lcm_A3 == gcd_B3}")

